<?php
use Aegis\Persistence\AuditRepository;
use Aegis\Persistence\SportsRepository;
use Aegis\Sports\DecisionRecorder;
test('sports decision recorder persists versioned traceable decision', function () {
 $repo = new class implements SportsRepository { public array $row=[]; public function ensureProvider(string $a,string $b):array{return[];} public function saveHealth(int $a,array $b):void{} public function saveMatch(int $a,array $b):array{return[];} public function findMatch(int $a,string $b):?array{return null;} public function saveOdds(int $a,int $b,array $c):void{} public function saveQuality(int $a,array $b):void{} public function startSync(array $a):?array{return null;} public function finishSync(string $a,array $b):void{} public function ensureModelVersion(array $a):int{return 3;} public function savePrediction(array $p):void{$this->row=$p;} public function saveTicket(array $a):void{} public function saveTicketSelection(array $a):void{} public function ticketSelections(string $a):array{return [];} public function updateTicketSelection(int $a,array $b):void{} public function findTicket(string $a):?array{return null;} public function updateTicket(string $a,array $b):void{} }; $audit=new class implements AuditRepository {public function emit(string $a,string $b,array $c=[],string $d='system'):void{} public function recent(int $a=100):array{return[];}};
 $id=(new DecisionRecorder($repo,$audit))->recordPrediction(9,['modelName'=>'M','modelVersion'=>'1','featureVersion'=>'f','calibrationVersion'=>'c','decision'=>'PREDICTION_READY','market'=>'TOTAL','selection'=>'OVER','rawModelProbability'=>.7,'calibratedProbability'=>.68],['impliedProbability'=>.6,'expectedValue'=>.1],['classification'=>'LOW','reasons'=>[]],['score'=>90],['correlation'=>'LOW']); assert_contains('prd_', $id); assert_equals(9,$repo->row['match_id']); assert_equals('PREDICTION_READY',$repo->row['decision']);
});
